import{_ as a,o,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-07-29/nav2_common_01_package_boundary.png",c="/Nav2ArticlesSite/article-assets/2026-07-29/nav2_common_05_multirobot_pose.png",n="/Nav2ArticlesSite/article-assets/2026-07-29/nav2_common_04_launch_branch_tools.png",r="/Nav2ArticlesSite/article-assets/2026-07-29/nav2_common_02_rewritten_yaml_pipeline.png",d="/Nav2ArticlesSite/article-assets/2026-07-29/nav2_common_03_rewrite_matching.png",s="/Nav2ArticlesSite/article-assets/2026-07-29/nav2_common_06_cmake_contract.png",k=JSON.parse('{"title":"没有一个 ROS 节点，却在启动前改写整套 Nav2：逐函数拆解 nav2_common 的 32 个入口","description":"打开 nav2common，你找不到订阅器、发布器、Action Server，也找不到 main()。但 Nav2 启动时使用哪张地图、是否使用仿真时间、参数是否包进机器人命名空间、RViz Topic 是否加前缀，以及数十个 C++ 包用什么标准和告警规则编译，都可能经过它。","frontmatter":{"title":"没有一个 ROS 节点，却在启动前改写整套 Nav2：逐函数拆解 nav2_common 的 32 个入口","description":"打开 nav2common，你找不到订阅器、发布器、Action Server，也找不到 main()。但 Nav2 启动时使用哪张地图、是否使用仿真时间、参数是否包进机器人命名空间、RViz Topic 是否加前缀，以及数十个 C++ 包用什么标准和告警规则编译，都可能经过它。","date":"2026-07-29","topic":"Nav2 工程实践","section":"五 · 平滑器与基础工具","readingTime":22,"source":"2026-07-29/nav2_common_32_entries_source_walkthrough.md","status":"published","cover":"/article-assets/2026-07-29/nav2_common_01_package_boundary.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-common-32-entries-source-walkthrough"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"没有一个 ROS 节点，却在启动前改写整套 Nav2：逐函数拆解 nav2_common 的 32 个入口"}],["meta",{"property":"og:description","content":"打开 nav2common，你找不到订阅器、发布器、Action Server，也找不到 main()。但 Nav2 启动时使用哪张地图、是否使用仿真时间、参数是否包进机器人命名空间、RViz Topic 是否加前缀，以及数十个 C++ 包用什么标准和告警规则编译，都可能经过它。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-common-32-entries-source-walkthrough"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-29/nav2_common_01_package_boundary.png"}],["meta",{"property":"article:published_time","content":"2026-07-29"}],["meta",{"name":"twitter:title","content":"没有一个 ROS 节点，却在启动前改写整套 Nav2：逐函数拆解 nav2_common 的 32 个入口"}],["meta",{"name":"twitter:description","content":"打开 nav2common，你找不到订阅器、发布器、Action Server，也找不到 main()。但 Nav2 启动时使用哪张地图、是否使用仿真时间、参数是否包进机器人命名空间、RViz Topic 是否加前缀，以及数十个 C++ 包用什么标准和告警规则编译，都可能经过它。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-29/nav2_common_01_package_boundary.png"}]],"prev":{"text":"Nav2 的规划、控制、恢复为何都离不开它？逐函数拆解 nav2_util 的 128 个公共入口","link":"/nav2/nav2-util-128-functions-source-walkthrough"},"next":{"text":"一条 Path，如何被四个残差“拉顺又避障”？拆解 Nav2 Constrained Smoother 的 Ceres 公式","link":"/nav2/nav2-constrained-smoother-source-walkthrough"}},"headers":[],"relativePath":"nav2/nav2-common-32-entries-source-walkthrough.md","filePath":"nav2/nav2-common-32-entries-source-walkthrough.md","lastUpdated":null}'),u={name:"nav2/nav2-common-32-entries-source-walkthrough.md"};function p(h,e,m,_,b,v){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="没有一个-ros-节点-却在启动前改写整套-nav2-逐函数拆解-nav2-common-的-32-个入口" tabindex="-1">没有一个 ROS 节点，却在启动前改写整套 Nav2：逐函数拆解 nav2_common 的 32 个入口 <a class="header-anchor" href="#没有一个-ros-节点-却在启动前改写整套-nav2-逐函数拆解-nav2-common-的-32-个入口" aria-label="Permalink to &quot;没有一个 ROS 节点，却在启动前改写整套 Nav2：逐函数拆解 nav2_common 的 32 个入口&quot;">​</a></h1><p>打开 <code>nav2_common</code>，你找不到订阅器、发布器、Action Server，也找不到 <code>main()</code>。但 Nav2 启动时使用哪张地图、是否使用仿真时间、参数是否包进机器人命名空间、RViz Topic 是否加前缀，以及数十个 C++ 包用什么标准和告警规则编译，都可能经过它。</p><p>它做的事情发生在机器人开始导航之前。Python 部分嵌入 ROS 2 Launch 的替换机制，把命令行参数、YAML 和 RViz 配置变成运行期临时文件；CMake 部分通过 <code>find_package(nav2_common)</code> 向下游导出统一宏，把构建约束铺到规划、控制、地图、行为等包。</p><p>本文以本地 <code>navigation2</code>、包版本 <code>1.1.20</code> 为事实基线。生产源码共有 31 个 Python 函数／方法，另有 1 个公开 CMake 宏，合计 32 个入口。内部递归函数 <code>process_value()</code> 也单独计入，因为它承担了完整的数据遍历职责。</p><h2 id="一、先把结论说清楚" tabindex="-1">一、先把结论说清楚 <a class="header-anchor" href="#一、先把结论说清楚" aria-label="Permalink to &quot;一、先把结论说清楚&quot;">​</a></h2><h3 id="_1-1-它不是运行期-ros-节点" tabindex="-1">1.1 它不是运行期 ROS 节点 <a class="header-anchor" href="#_1-1-它不是运行期-ros-节点" aria-label="Permalink to &quot;1.1 它不是运行期 ROS 节点&quot;">​</a></h3><p><code>nav2_common</code> 不创建 Topic、Action、Service、Timer 或 Executor。本文提到的“回调”主要指 Launch 系统在需要一个 Substitution 的最终文本时调用 <code>perform(context)</code>，不是 ROS 消息到达后触发的回调。</p><p>这一区别很重要。<code>RewrittenYaml</code> 改的是节点启动前要读取的配置文件路径，并不会在节点已经运行后监听参数变化。运行期动态参数仍要由具体节点自己的参数回调处理。</p><h3 id="_1-2-它同时工作在两个时间平面" tabindex="-1">1.2 它同时工作在两个时间平面 <a class="header-anchor" href="#_1-2-它同时工作在两个时间平面" aria-label="Permalink to &quot;1.2 它同时工作在两个时间平面&quot;">​</a></h3><ul><li>Launch 平面发生在启动描述展开和进程参数组装期间，输入是 LaunchConfiguration、文件和命令行文本，输出通常是临时文件路径或条件判断文本。</li><li>CMake 平面发生在配置与编译期间，输入是下游项目当前的 CMake 状态，输出是目录级编译、链接和平台规则。</li></ul><p>两个平面没有共享运行状态。它们只是被放在同一个“公共基础设施包”里统一分发。</p><h3 id="_1-3-它修改副本-不修改原配置" tabindex="-1">1.3 它修改副本，不修改原配置 <a class="header-anchor" href="#_1-3-它修改副本-不修改原配置" aria-label="Permalink to &quot;1.3 它修改副本，不修改原配置&quot;">​</a></h3><p><code>RewrittenYaml</code> 和条件成立时的 <code>ReplaceString</code> 都创建 <code>NamedTemporaryFile(delete=False)</code>。原始 YAML 或 RViz 文件保持不变，Launch 后续拿到的是新文件路径。</p><p>这保证了多机器人启动时可以从同一份模板生成多个命名空间版本，但也意味着临时文件不会由本包自动删除。长时间频繁拉起 Launch 时，系统临时目录可能积累历史副本。</p><h3 id="_1-4-公共-不等于-没有边界" tabindex="-1">1.4 “公共”不等于“没有边界” <a class="header-anchor" href="#_1-4-公共-不等于-没有边界" aria-label="Permalink to &quot;1.4 “公共”不等于“没有边界”&quot;">​</a></h3><p><code>RewrittenYaml</code> 不是通用 YAML Schema 引擎；<code>ReplaceString</code> 也不是语法感知的配置编辑器。前者依赖点分路径、同名键和 <code>ros__parameters</code> 约定，后者只是逐行字符串替换。输入格式超出这些假设时，源码可能跳过、部分写入或直接抛异常。</p><p><img src="'+l+'" alt="nav2_common 的 Launch 与 CMake 双平面边界"></p><h2 id="二、包边界与真实调用链" tabindex="-1">二、包边界与真实调用链 <a class="header-anchor" href="#二、包边界与真实调用链" aria-label="Permalink to &quot;二、包边界与真实调用链&quot;">​</a></h2><h3 id="_2-1-python-导出边界" tabindex="-1">2.1 Python 导出边界 <a class="header-anchor" href="#_2-1-python-导出边界" aria-label="Permalink to &quot;2.1 Python 导出边界&quot;">​</a></h3><p><code>nav2_common/launch/__init__.py</code> 没有定义函数，只把四个类重新导出：<code>HasNodeParams</code>、<code>RewrittenYaml</code>、<code>ReplaceString</code> 和 <code>ParseMultiRobotPose</code>。因此包外 Launch 通常写：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> nav2_common.launch </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RewrittenYaml</span></span></code></pre></div><p><code>nav2_common/__init__.py</code> 本身为空。源码树中的 <code>__pycache__</code> 是 Python 生成物，不是新的接口，也不纳入函数统计。</p><h3 id="_2-2-launch-substitution-数据流" tabindex="-1">2.2 Launch Substitution 数据流 <a class="header-anchor" href="#_2-2-launch-substitution-数据流" aria-label="Permalink to &quot;2.2 Launch Substitution 数据流&quot;">​</a></h3><p>典型调用链是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LaunchConfiguration</span></span>\n<span class="line"><span>  → RewrittenYaml／ReplaceString 对象</span></span>\n<span class="line"><span>  → ParameterFile 或 Node 参数消费该对象</span></span>\n<span class="line"><span>  → Launch 调用 perform(context)</span></span>\n<span class="line"><span>  → 返回临时文件路径</span></span>\n<span class="line"><span>  → 节点进程读取最终配置</span></span></code></pre></div><p>构造函数只保存尚未解析的 Substitution。真正的命名空间、地图路径、仿真时间等值，要等 <code>LaunchContext</code> 已经包含启动参数后才能解析。这就是“延迟求值”的意义。</p><h3 id="_2-3-cmake-导出数据流" tabindex="-1">2.3 CMake 导出数据流 <a class="header-anchor" href="#_2-3-cmake-导出数据流" aria-label="Permalink to &quot;2.3 CMake 导出数据流&quot;">​</a></h3><p><code>nav2_common</code> 自身用 <code>ament_python_install_package(nav2_common)</code> 安装 Python 包，用普通 <code>install(DIRECTORY cmake ...)</code> 安装宏文件，并通过 <code>ament_package(CONFIG_EXTRAS &quot;nav2_common-extras.cmake&quot;)</code> 导出额外 CMake 配置。</p><p>下游执行 <code>find_package(nav2_common REQUIRED)</code> 时，Ament 加载 extras 文件；extras 再 <code>include()</code> 宏文件。此后下游当前目录才能调用 <code>nav2_package()</code>。</p><h2 id="三、hasnodeparams-的四个函数" tabindex="-1">三、HasNodeParams 的四个函数 <a class="header-anchor" href="#三、hasnodeparams-的四个函数" aria-label="Permalink to &quot;三、HasNodeParams 的四个函数&quot;">​</a></h2><h3 id="_3-1-hasnodeparams-init" tabindex="-1">3.1 <code>HasNodeParams.__init__()</code> <a class="header-anchor" href="#_3-1-hasnodeparams-init" aria-label="Permalink to &quot;3.1 `HasNodeParams.__init__()`&quot;">​</a></h3><ul><li>作用：构造一个“参数文件是否包含指定节点顶层键”的 Launch Substitution。</li><li>输入：<code>source_file</code> 可以是字符串或其他 Launch Substitution；<code>node_name</code> 是普通文本。</li><li>输出：没有直接返回业务数据；对象内部保存规范化后的源文件 Substitution 列表和节点名。</li><li>数据流／回调：调用 <code>normalize_to_list_of_substitutions()</code>，让源路径可以延迟到 <code>LaunchContext</code> 中解析。</li><li>包外调用：当前仓库只在 <code>nav2_bringup/launch/slam_launch.py</code> 实例化一次，用来检查参数文件是否含 <code>slam_toolbox</code>。</li></ul><p><code>node_name</code> 没有像 <code>source_file</code> 一样被规范化。因此这个实现适合构造时就确定的节点名，不适合把节点名本身做成 LaunchConfiguration。</p><h3 id="_3-2-hasnodeparams-name" tabindex="-1">3.2 <code>HasNodeParams.name</code> <a class="header-anchor" href="#_3-2-hasnodeparams-name" aria-label="Permalink to &quot;3.2 `HasNodeParams.name`&quot;">​</a></h3><ul><li>作用：暴露源文件对应的 Substitution 列表。</li><li>输入：没有显式输入，读取私有成员 <code>__source_file</code>。</li><li>输出：<code>List[launch.Substitution]</code>。</li><li>数据流／回调：<code>perform()</code> 通过这个属性取得待解析的源文件表达式。</li><li>包外调用：当前仓库没有直接读取该属性的包外代码；它主要服务类内 <code>perform()</code>。</li></ul><p>属性名叫 <code>name</code>，实际保存的是文件路径表达式，不是节点名。读源码时不要被命名误导。</p><h3 id="_3-3-hasnodeparams-describe" tabindex="-1">3.3 <code>HasNodeParams.describe()</code> <a class="header-anchor" href="#_3-3-hasnodeparams-describe" aria-label="Permalink to &quot;3.3 `HasNodeParams.describe()`&quot;">​</a></h3><ul><li>作用：满足 Launch Substitution 的描述接口。</li><li>输入：没有显式输入。</li><li>输出：空字符串。</li><li>数据流／回调：Launch 在日志或实体描述场景下可以调用，但这里没有提供可读内容。</li><li>包外调用：没有发现生产代码显式调用，由 Launch 基类契约间接使用。</li></ul><p>空描述不影响条件判断，但会降低 Launch 调试输出的可解释性。</p><h3 id="_3-4-hasnodeparams-perform" tabindex="-1">3.4 <code>HasNodeParams.perform()</code> <a class="header-anchor" href="#_3-4-hasnodeparams-perform" aria-label="Permalink to &quot;3.4 `HasNodeParams.perform()`&quot;">​</a></h3><ul><li>作用：真正读取 YAML，并判断目标节点名是否为顶层键。</li><li>输入：当前 <code>LaunchContext</code>。</li><li>输出：文本 <code>&quot;True&quot;</code> 或 <code>&quot;False&quot;</code>，不是 Python 布尔值。</li><li>数据流／回调：Launch 条件求值时触发；先解析文件路径，再用 <code>yaml.safe_load()</code> 读取，最后检查 <code>self.__node_name in data.keys()</code>。</li><li>包外调用：<code>slam_launch.py</code> 把同一个对象分别交给 <code>UnlessCondition</code> 与 <code>IfCondition</code>。没有 <code>slam_toolbox</code> 参数时走默认配置分支；存在时把用户参数文件传给 SLAM Toolbox。</li></ul><p>返回文本是为了直接适配 Launch 条件表达式。源码假定 YAML 顶层一定是映射；空文件会得到 <code>None</code>，列表顶层也没有预期的键语义，两者都可能在 <code>data.keys()</code> 处失败。文件通过 <code>open()</code> 直接交给 <code>safe_load()</code>，没有使用上下文管理器显式关闭。</p><h2 id="四、parsemultirobotpose-的三个函数" tabindex="-1">四、ParseMultiRobotPose 的三个函数 <a class="header-anchor" href="#四、parsemultirobotpose-的三个函数" aria-label="Permalink to &quot;四、ParseMultiRobotPose 的三个函数&quot;">​</a></h2><h3 id="_4-1-parsemultirobotpose-init" tabindex="-1">4.1 <code>ParseMultiRobotPose.__init__()</code> <a class="header-anchor" href="#_4-1-parsemultirobotpose-init" aria-label="Permalink to &quot;4.1 `ParseMultiRobotPose.__init__()`&quot;">​</a></h3><ul><li>作用：创建多机器人位姿解析器，并立即保存目标命令行参数的原始值。</li><li>输入：目标参数名，例如 <code>&quot;robots&quot;</code>。</li><li>输出：没有直接返回值；私有成员 <code>__args</code> 保存解析结果。</li><li>数据流／回调：构造期间同步调用 <code>__parse_argument()</code>，不是 Launch 延迟求值。</li><li>包外调用：当前只在 <code>nav2_bringup/launch/cloned_multi_tb3_simulation_launch.py</code> 中以 <code>ParseMultiRobotPose(&#39;robots&#39;).value()</code> 使用。</li></ul><p>这个类没有继承 <code>launch.Substitution</code>。它读取的是生成 LaunchDescription 时进程已经拥有的 <code>sys.argv</code>，因此工作时机比 <code>RewrittenYaml.perform()</code> 更早，也不能随 LaunchContext 变化。</p><h3 id="_4-2-parsemultirobotpose-parse-argument" tabindex="-1">4.2 <code>ParseMultiRobotPose.__parse_argument()</code> <a class="header-anchor" href="#_4-2-parsemultirobotpose-parse-argument" aria-label="Permalink to &quot;4.2 `ParseMultiRobotPose.__parse_argument()`&quot;">​</a></h3><ul><li>作用：从 ROS 2 Launch 进程命令行中取出 <code>&lt;target&gt;:=&lt;value&gt;</code>。</li><li>输入：目标参数名。</li><li>输出：找到时返回去掉前缀的原始文本；找不到时返回空字符串。</li><li>数据流／回调：只有 <code>len(sys.argv) &gt; 4</code> 才扫描，并固定跳过前四项；遇到第一个匹配项立即返回。</li><li>包外调用：私有函数，只由构造函数调用。</li></ul><p>实现通过 <code>startswith()</code> 判断前缀，再用 <code>replace()</code> 删除前缀。它依赖 <code>ros2 launch</code> 当前的命令行排列约定，不读取 LaunchConfiguration，也不处理同名参数的后续重复定义。</p><h3 id="_4-3-parsemultirobotpose-value" tabindex="-1">4.3 <code>ParseMultiRobotPose.value()</code> <a class="header-anchor" href="#_4-3-parsemultirobotpose-value" aria-label="Permalink to &quot;4.3 `ParseMultiRobotPose.value()`&quot;">​</a></h3><ul><li>作用：把多机器人文本变成“机器人名到六自由度位姿字典”的映射。</li><li>输入：隐式读取构造时保存的原始字符串。</li><li>输出：<code>Dict</code>；没有参数时返回空字典。</li><li>数据流／回调：按分号拆机器人项，按等号拆名称和 Pose，使用 <code>yaml.safe_load()</code> 解析花括号内容，再为缺失的 <code>x</code>、<code>y</code>、<code>z</code>、<code>roll</code>、<code>pitch</code>、<code>yaw</code> 补 <code>0.0</code>。</li><li>包外调用：克隆多机器人 Launch 遍历返回字典，为每个机器人创建 namespace、初始 Pose 和一组 Bringup Action。</li></ul><p>等号拆分没有设置最大次数，拆出数量不是二时直接跳过。重复机器人名会被后项覆盖。源码也没有验证 Pose 的类型；如果 YAML 解析成标量或空值，后续成员检查可能抛异常。</p><p><img src="'+c+'" alt="多机器人命令行参数到六自由度 Pose 字典"></p><h2 id="五、replacestring-的七个函数" tabindex="-1">五、ReplaceString 的七个函数 <a class="header-anchor" href="#五、replacestring-的七个函数" aria-label="Permalink to &quot;五、ReplaceString 的七个函数&quot;">​</a></h2><h3 id="_5-1-replacestring-init" tabindex="-1">5.1 <code>ReplaceString.__init__()</code> <a class="header-anchor" href="#_5-1-replacestring-init" aria-label="Permalink to &quot;5.1 `ReplaceString.__init__()`&quot;">​</a></h3><ul><li>作用：保存源文件、字符串替换表和可选条件。</li><li>输入：<code>source_file</code>、<code>replacements</code> 字典，以及可选 <code>launch.Condition</code>。</li><li>输出：一个可延迟执行的 Launch Substitution。</li><li>数据流／回调：源文件和每个替换值都经过 <code>normalize_to_list_of_substitutions()</code>；替换键本身保持原对象。</li><li>包外调用：标准 Bringup 用它改多机器人参数模板和 RViz 配置；本项目 <code>myagv_test_bringup</code>、<code>nav2_regulated_modules</code> 的 RViz Launch 也在使用。</li></ul><p>替换值可以由 <code>(&#39;/&#39;, namespace)</code> 这种 Substitution 序列组成，直到 LaunchContext 就绪后才拼成真实文本。替换键必须最终是字符串，否则执行阶段会抛 <code>TypeError</code>。</p><h3 id="_5-2-replacestring-name" tabindex="-1">5.2 <code>ReplaceString.name</code> <a class="header-anchor" href="#_5-2-replacestring-name" aria-label="Permalink to &quot;5.2 `ReplaceString.name`&quot;">​</a></h3><ul><li>作用：返回源文件 Substitution 列表。</li><li>输入：没有显式输入。</li><li>输出：<code>List[launch.Substitution]</code>。</li><li>数据流／回调：<code>perform()</code> 用它解析真实文件路径。</li><li>包外调用：没有发现直接包外调用。</li></ul><p>与 <code>HasNodeParams.name</code> 一样，这个名字表示“被替换的源”，不是文件内的配置名称。</p><h3 id="_5-3-replacestring-condition" tabindex="-1">5.3 <code>ReplaceString.condition</code> <a class="header-anchor" href="#_5-3-replacestring-condition" aria-label="Permalink to &quot;5.3 `ReplaceString.condition`&quot;">​</a></h3><ul><li>作用：暴露构造时保存的可选条件。</li><li>输入：没有显式输入。</li><li>输出：<code>launch.Condition</code> 或 <code>None</code>。</li><li>数据流／回调：<code>perform()</code> 读取它，决定生成替换副本还是直接返回原路径。</li><li>包外调用：没有发现直接包外调用。</li></ul><p>条件只控制文件是否改写，不控制引用该 Substitution 的整个 Node 是否启动。</p><h3 id="_5-4-replacestring-describe" tabindex="-1">5.4 <code>ReplaceString.describe()</code> <a class="header-anchor" href="#_5-4-replacestring-describe" aria-label="Permalink to &quot;5.4 `ReplaceString.describe()`&quot;">​</a></h3><ul><li>作用：满足 Launch Substitution 描述接口。</li><li>输入：没有显式输入。</li><li>输出：空字符串。</li><li>数据流／回调：可能由 Launch 的描述和调试路径间接触发。</li><li>包外调用：没有显式调用点。</li></ul><h3 id="_5-5-replacestring-perform" tabindex="-1">5.5 <code>ReplaceString.perform()</code> <a class="header-anchor" href="#_5-5-replacestring-perform" aria-label="Permalink to &quot;5.5 `ReplaceString.perform()`&quot;">​</a></h3><ul><li>作用：根据条件返回原文件路径，或生成完成文本替换的临时副本。</li><li>输入：当前 <code>LaunchContext</code>。</li><li>输出：原路径或临时文件路径。</li><li>数据流／回调：先解析源路径；条件成立时创建输出文件，调用 <code>resolve_replacements()</code> 和 <code>replace()</code>，关闭输入输出后返回临时路径。</li><li>包外调用：由 ParameterFile、Node 的 <code>arguments</code> 等 Launch 消费者间接触发。</li></ul><p>当前仓库共有四个实际实例。标准 <code>bringup_launch.py</code> 的参数模板替换受 <code>use_namespace</code> 条件控制；三个 RViz Launch 则在命名空间分支实际消费替换后的配置。</p><p>异常处理有一个值得注意的缺口。<code>replace()</code> 抛错后，函数只打印错误，仍可能返回空或部分写入的临时文件；如果源文件连 <code>open()</code> 都失败，<code>finally</code> 又会调用尚未赋值的 <code>input_file.close()</code>，新的局部变量异常会覆盖原始文件错误。</p><h3 id="_5-6-replacestring-resolve-replacements" tabindex="-1">5.6 <code>ReplaceString.resolve_replacements()</code> <a class="header-anchor" href="#_5-6-replacestring-resolve-replacements" aria-label="Permalink to &quot;5.6 `ReplaceString.resolve_replacements()`&quot;">​</a></h3><ul><li>作用：把替换表中的延迟值解析成最终文本。</li><li>输入：当前 <code>LaunchContext</code>。</li><li>输出：普通字典，键保持不变，值变成字符串。</li><li>数据流／回调：逐项调用 <code>launch.utilities.perform_substitutions()</code>。</li><li>包外调用：没有包外调用，只由 <code>perform()</code> 使用。</li></ul><p>例如值 <code>(&#39;/&#39;, namespace)</code> 会在这里变成 <code>/robot1</code>。同一个 ReplaceString 对象在不同 Context 中理论上可以解析出不同结果。</p><h3 id="_5-7-replacestring-replace" tabindex="-1">5.7 <code>ReplaceString.replace()</code> <a class="header-anchor" href="#_5-7-replacestring-replace" aria-label="Permalink to &quot;5.7 `ReplaceString.replace()`&quot;">​</a></h3><ul><li>作用：执行不理解文件语法的逐行全局字符串替换。</li><li>输入：可迭代输入文件、可写输出文件、已经解析的替换字典。</li><li>输出：没有返回值；结果写入输出文件。</li><li>数据流／回调：每读一行，就按字典插入顺序检查全部替换对；命中时用 Python<code>str.replace()</code> 替换该行所有出现位置。</li><li>包外调用：没有包外调用，只由 <code>perform()</code> 使用。</li></ul><p>它不会解析 YAML、RViz 或 XML，也不会区分注释、键、值和普通文本。较早的替换结果还可能再次命中较晚的替换键，因此多个替换对存在顺序效应。</p><p><img src="'+n+'" alt="文本替换与参数存在性判断的两类 Launch 分支"></p><h2 id="六、dictitemreference-的三个函数" tabindex="-1">六、DictItemReference 的三个函数 <a class="header-anchor" href="#六、dictitemreference-的三个函数" aria-label="Permalink to &quot;六、DictItemReference 的三个函数&quot;">​</a></h2><h3 id="_6-1-dictitemreference-init" tabindex="-1">6.1 <code>DictItemReference.__init__()</code> <a class="header-anchor" href="#_6-1-dictitemreference-init" aria-label="Permalink to &quot;6.1 `DictItemReference.__init__()`&quot;">​</a></h3><ul><li>作用：把“某个字典中的某个键”包装成可原地更新的轻量引用。</li><li>输入：目标字典和目标键。</li><li>输出：一个保存字典对象与键名的引用对象。</li><li>数据流／回调：不复制字典，后续写入会直接反映到原 YAML 对象。</li><li>包外调用：没有包外调用；由 <code>RewrittenYaml.getYamlLeafKeys()</code> 创建。</li></ul><p>Python 普通标量没有 C++ 引用语义，这个包装器让遍历函数既能告诉调用者“发现了哪个键”，又能让调用者覆盖对应值。</p><h3 id="_6-2-dictitemreference-key" tabindex="-1">6.2 <code>DictItemReference.key()</code> <a class="header-anchor" href="#_6-2-dictitemreference-key" aria-label="Permalink to &quot;6.2 `DictItemReference.key()`&quot;">​</a></h3><ul><li>作用：读取被引用的键名。</li><li>输入：没有显式输入。</li><li>输出：字符串键名。</li><li>数据流／回调：<code>substitute_params()</code> 用返回值查询同名改写表。</li><li>包外调用：没有包外调用。</li></ul><h3 id="_6-3-dictitemreference-setvalue" tabindex="-1">6.3 <code>DictItemReference.setValue()</code> <a class="header-anchor" href="#_6-3-dictitemreference-setvalue" aria-label="Permalink to &quot;6.3 `DictItemReference.setValue()`&quot;">​</a></h3><ul><li>作用：原地覆盖被引用键的值。</li><li>输入：新的 YAML 标量值。</li><li>输出：没有返回值。</li><li>数据流／回调：执行 <code>dictionary[dictKey] = value</code>，直接修改 <code>safe_load()</code> 生成的数据树。</li><li>包外调用：没有包外调用，只由 <code>substitute_params()</code> 使用。</li></ul><p>类型注解把字典值写成 <code>YamlValue</code>，但遍历过程中引用也可能指向一个嵌套字典。运行时 Python 不强制这个注解。</p><h2 id="七、rewrittenyaml-的入口与总流水线" tabindex="-1">七、RewrittenYaml 的入口与总流水线 <a class="header-anchor" href="#七、rewrittenyaml-的入口与总流水线" aria-label="Permalink to &quot;七、RewrittenYaml 的入口与总流水线&quot;">​</a></h2><h3 id="_7-1-rewrittenyaml-init" tabindex="-1">7.1 <code>RewrittenYaml.__init__()</code> <a class="header-anchor" href="#_7-1-rewrittenyaml-init" aria-label="Permalink to &quot;7.1 `RewrittenYaml.__init__()`&quot;">​</a></h3><ul><li>作用：保存 YAML 源与四类改写策略，等待 LaunchContext 就绪后执行。</li><li>输入：源文件、<code>param_rewrites</code>、可选 <code>root_key</code>、可选 <code>key_rewrites</code>、可选 <code>value_rewrites</code>、<code>convert_types</code>。</li><li>输出：一个 Launch Substitution 对象。</li><li>数据流／回调：源文件、三组改写目标值和根键都被规范化为 Substitution 列表；键仍保留为普通 Python 字典键。</li><li>包外调用：全仓有 25 个实际实例，是本包最常用的接口。</li></ul><p>生产 Bringup 常把 <code>use_sim_time</code>、<code>autostart</code>、<code>yaml_filename</code> 放入 <code>param_rewrites</code>，把 namespace 放入 <code>root_key</code>，并开启 <code>convert_types=True</code>。</p><h3 id="_7-2-rewrittenyaml-name" tabindex="-1">7.2 <code>RewrittenYaml.name</code> <a class="header-anchor" href="#_7-2-rewrittenyaml-name" aria-label="Permalink to &quot;7.2 `RewrittenYaml.name`&quot;">​</a></h3><ul><li>作用：返回源 YAML 的 Substitution 列表。</li><li>输入：没有显式输入。</li><li>输出：<code>list[launch.Substitution]</code>。</li><li>数据流／回调：总入口 <code>perform()</code> 用它解析实际文件路径。</li><li>包外调用：没有直接包外调用。</li></ul><h3 id="_7-3-rewrittenyaml-describe" tabindex="-1">7.3 <code>RewrittenYaml.describe()</code> <a class="header-anchor" href="#_7-3-rewrittenyaml-describe" aria-label="Permalink to &quot;7.3 `RewrittenYaml.describe()`&quot;">​</a></h3><ul><li>作用：满足 Launch Substitution 描述接口。</li><li>输入：没有显式输入。</li><li>输出：空字符串。</li><li>数据流／回调：只参与 Launch 实体描述契约，不改 YAML。</li><li>包外调用：没有显式调用点。</li></ul><h3 id="_7-4-rewrittenyaml-perform" tabindex="-1">7.4 <code>RewrittenYaml.perform()</code> <a class="header-anchor" href="#_7-4-rewrittenyaml-perform" aria-label="Permalink to &quot;7.4 `RewrittenYaml.perform()`&quot;">​</a></h3><ul><li>作用：组织一次完整 YAML 改写，并返回临时文件路径。</li><li>输入：当前 <code>LaunchContext</code>。</li><li>输出：包含最终 YAML 的临时文件路径。</li><li>数据流／回调：解析源路径，创建临时文件，调用 <code>resolve_rewrites()</code>，安全加载 YAML，然后依次执行参数替换、参数新增、键替换、值替换、可选根键包装和 <code>yaml.dump()</code>。</li><li>包外调用：由 <code>ParameterFile</code> 或其他 Launch 参数消费者间接触发。</li></ul><p>顺序固定为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>substitute_params</span></span>\n<span class="line"><span>  → add_params</span></span>\n<span class="line"><span>  → substitute_keys</span></span>\n<span class="line"><span>  → substitute_values</span></span>\n<span class="line"><span>  → root_key 包装</span></span>\n<span class="line"><span>  → yaml.dump</span></span></code></pre></div><p>后执行的阶段可以覆盖前阶段的结果。例如先把键名改掉，再按值表匹配改名后的内容。输出是重新序列化的 YAML，因此原注释和排版不会保留。</p><h3 id="_7-5-rewrittenyaml-resolve-rewrites" tabindex="-1">7.5 <code>RewrittenYaml.resolve_rewrites()</code> <a class="header-anchor" href="#_7-5-rewrittenyaml-resolve-rewrites" aria-label="Permalink to &quot;7.5 `RewrittenYaml.resolve_rewrites()`&quot;">​</a></h3><ul><li>作用：把参数、键和值三组改写目标解析成普通字符串。</li><li>输入：当前 <code>LaunchContext</code>。</li><li>输出：三个 <code>dict[str, str]</code>。</li><li>数据流／回调：逐项调用 <code>perform_substitutions()</code>，保持改写表的键不变。</li><li>包外调用：没有包外调用，只由 <code>perform()</code> 调用。</li></ul><p>这个函数只解析“要写入什么”，不检查源 YAML 是否存在对应路径。存在性与创建逻辑属于后续函数。</p><p><img src="'+r+'" alt="RewrittenYaml 从 LaunchContext 到临时 YAML 的固定流水线"></p><h2 id="八、rewrittenyaml-的参数路径与类型函数" tabindex="-1">八、RewrittenYaml 的参数路径与类型函数 <a class="header-anchor" href="#八、rewrittenyaml-的参数路径与类型函数" aria-label="Permalink to &quot;八、RewrittenYaml 的参数路径与类型函数&quot;">​</a></h2><h3 id="_8-1-rewrittenyaml-substitute-params" tabindex="-1">8.1 <code>RewrittenYaml.substitute_params()</code> <a class="header-anchor" href="#_8-1-rewrittenyaml-substitute-params" aria-label="Permalink to &quot;8.1 `RewrittenYaml.substitute_params()`&quot;">​</a></h3><ul><li>作用：替换已有参数，支持同名键匹配和点分绝对路径匹配。</li><li>输入：YAML 数据树和已经解析的参数改写表。</li><li>输出：没有返回值；原地修改数据树。</li><li>数据流／回调：先遍历 <code>getYamlLeafKeys()</code>，所有同名键都被替换；再用 <code>pathify()</code> 枚举叶路径，对命中的绝对路径调用 <code>updateYamlPathVals()</code>。</li><li>包外调用：没有包外调用，只由 <code>perform()</code> 使用。</li></ul><p>同名改写是全树范围。例如不同节点各有一个 <code>use_sim_time</code>，一条改写会同时覆盖它们。绝对路径阶段随后执行，所以更精确的路径项可以覆盖同名阶段刚写入的值。</p><p>源码注释说“只替换叶参数”，但 <code>getYamlLeafKeys()</code> 在递归后也会为映射值的父键生成引用。如果改写表正好包含这个父键，整个子映射也可能被标量替换。</p><h3 id="_8-2-rewrittenyaml-add-params" tabindex="-1">8.2 <code>RewrittenYaml.add_params()</code> <a class="header-anchor" href="#_8-2-rewrittenyaml-add-params" aria-label="Permalink to &quot;8.2 `RewrittenYaml.add_params()`&quot;">​</a></h3><ul><li>作用：创建源 YAML 中不存在的新 ROS 参数路径。</li><li>输入：YAML 数据树与参数改写表。</li><li>输出：没有返回值；符合条件的路径被原地加入。</li><li>数据流／回调：重新调用 <code>pathify()</code> 获取现有叶路径；缺失路径只有包含 <code>ros__parameters</code> 段时才会送给 <code>updateYamlPathVals()</code>。</li><li>包外调用：没有包外调用，只由 <code>perform()</code> 使用。</li></ul><p>这个限制避免任意字符串在 YAML 顶层制造结构，但它只检查路径片段中是否出现精确文本 <code>ros__parameters</code>，并不验证完整 ROS 参数文件 Schema。</p><h3 id="_8-3-rewrittenyaml-updateyamlpathvals" tabindex="-1">8.3 <code>RewrittenYaml.updateYamlPathVals()</code> <a class="header-anchor" href="#_8-3-rewrittenyaml-updateyamlpathvals" aria-label="Permalink to &quot;8.3 `RewrittenYaml.updateYamlPathVals()`&quot;">​</a></h3><ul><li>作用：沿点分路径递归写入字典或列表。</li><li>输入：当前子树、剩余键列表和目标值。</li><li>输出：更新后的当前子树，同时原对象已被修改。</li><li>数据流／回调：逐层从 <code>yaml_key_list</code> 弹出路径；字典缺少中间键时以空字典创建，列表路径则把文本索引转换成整数。</li><li>包外调用：没有包外调用；由已有绝对路径替换和缺失参数新增共同使用。</li></ul><p>列表索引必须有效且可转成整数。点分路径也无法无歧义地区分“层级分隔符”和“原始键名自身的点号”。</p><h3 id="_8-4-rewrittenyaml-convert" tabindex="-1">8.4 <code>RewrittenYaml.convert()</code> <a class="header-anchor" href="#_8-4-rewrittenyaml-convert" aria-label="Permalink to &quot;8.4 `RewrittenYaml.convert()`&quot;">​</a></h3><ul><li>作用：把 Launch 解析出的文本转换成有限的 YAML 标量类型。</li><li>输入：字符串。</li><li>输出：<code>str</code>、<code>int</code>、<code>float</code> 或 <code>bool</code>。</li><li>数据流／回调：开启 <code>convert_types</code> 时，含点号的文本尝试转 <code>float</code>，否则尝试转 <code>int</code>；随后无论开关状态如何，都识别大小写不敏感的 <code>true</code> 与 <code>false</code>。</li><li>包外调用：没有包外调用；参数替换、新增参数和值替换都会使用。</li></ul><p>本地行为探针确认：<code>12</code> 变成整数，<code>3.5</code> 变成浮点数，<code>true</code> 与 <code>False</code> 变成布尔值；<code>1e-3</code> 因为不含点号而先尝试整数，失败后保持字符串，<code>null</code> 也保持字符串。这不是完整 YAML 标量推断器。</p><p><img src="'+d+'" alt="同名键、点分路径、新增参数与类型转换"></p><h2 id="九、rewrittenyaml-的键、值与递归函数" tabindex="-1">九、RewrittenYaml 的键、值与递归函数 <a class="header-anchor" href="#九、rewrittenyaml-的键、值与递归函数" aria-label="Permalink to &quot;九、RewrittenYaml 的键、值与递归函数&quot;">​</a></h2><h3 id="_9-1-rewrittenyaml-substitute-values" tabindex="-1">9.1 <code>RewrittenYaml.substitute_values()</code> <a class="header-anchor" href="#_9-1-rewrittenyaml-substitute-values" aria-label="Permalink to &quot;9.1 `RewrittenYaml.substitute_values()`&quot;">​</a></h3><ul><li>作用：启动对整棵 YAML 树的标量值替换。</li><li>输入：YAML 顶层字典和值改写表。</li><li>输出：没有返回值；顶层每个键对应的值都被递归处理结果覆盖。</li><li>数据流／回调：定义内部 <code>process_value()</code>，再遍历顶层键调用它。</li><li>包外调用：没有包外调用，只由 <code>perform()</code> 使用。</li></ul><p>值匹配通过 <code>str(value)</code> 完成，因此原值是整数、浮点数或布尔值时，也会先转换成字符串再查表。</p><h3 id="_9-2-rewrittenyaml-substitute-values-process-value" tabindex="-1">9.2 <code>RewrittenYaml.substitute_values.process_value()</code> <a class="header-anchor" href="#_9-2-rewrittenyaml-substitute-values-process-value" aria-label="Permalink to &quot;9.2 `RewrittenYaml.substitute_values.process_value()`&quot;">​</a></h3><ul><li>作用：递归遍历字典、列表和标量，并完成值级替换。</li><li>输入：任意当前 YAML 值。</li><li>输出：原字典、重建的列表、转换后的替换值，或原标量。</li><li>数据流／回调：字典逐项原地更新；列表用列表推导递归重建；标量字符串化后查询 <code>value_rewrites</code>，命中时调用 <code>convert()</code>。</li><li>包外调用：内部函数，只由 <code>substitute_values()</code> 及自身递归调用。</li></ul><p>这是 31 个 Python 入口中唯一的嵌套函数。把它单独统计，是因为列表中的字典能够被值替换完整遍历，而后面的键替换并不具备同样的列表递归能力。</p><h3 id="_9-3-rewrittenyaml-substitute-keys" tabindex="-1">9.3 <code>RewrittenYaml.substitute_keys()</code> <a class="header-anchor" href="#_9-3-rewrittenyaml-substitute-keys" aria-label="Permalink to &quot;9.3 `RewrittenYaml.substitute_keys()`&quot;">​</a></h3><ul><li>作用：递归修改字典键名。</li><li>输入：当前 YAML 字典与键改写表。</li><li>输出：没有返回值；字典结构被原地修改。</li><li>数据流／回调：复制当前键列表以避免遍历时改字典；命中时先写入新键再删除旧键；随后只对字典值继续递归。</li><li>包外调用：没有包外调用，只由 <code>perform()</code> 使用。</li></ul><p>它不会递归进入列表中的字典。新键已经存在时，源码直接覆盖目标值，没有冲突检测；原键随后删除。键改写属于结构操作，不适合在不了解完整 YAML 的情况下大范围使用。</p><h3 id="_9-4-rewrittenyaml-getyamlleafkeys" tabindex="-1">9.4 <code>RewrittenYaml.getYamlLeafKeys()</code> <a class="header-anchor" href="#_9-4-rewrittenyaml-getyamlleafkeys" aria-label="Permalink to &quot;9.4 `RewrittenYaml.getYamlLeafKeys()`&quot;">​</a></h3><ul><li>作用：深度优先生成可更新的字典键引用。</li><li>输入：当前 YAML 字典。</li><li>输出：<code>Generator[DictItemReference, None, None]</code>。</li><li>数据流／回调：非字典直接结束；遇到字典子节点先递归，再为当前层这个键生成引用。</li><li>包外调用：没有包外调用，只由 <code>substitute_params()</code> 使用。</li></ul><p>由于每个键最终都会 <code>yield</code>，函数名中的 Leaf 并不严格。叶值键和指向子字典的父键都会出现；列表内部的字典则不会进入。</p><h3 id="_9-5-rewrittenyaml-pathify" tabindex="-1">9.5 <code>RewrittenYaml.pathify()</code> <a class="header-anchor" href="#_9-5-rewrittenyaml-pathify" aria-label="Permalink to &quot;9.5 `RewrittenYaml.pathify()`&quot;">​</a></h3><ul><li>作用：把嵌套字典和列表展平为“点分路径到叶值”的字典。</li><li>输入：任意 YAML 子树、可选当前路径、可选结果字典和连接符。</li><li>输出：叶路径字典。</li><li>数据流／回调：入口调用时创建结果字典并从空路径递归；字典追加键，列表追加数字索引，只有标量叶值写入结果。</li><li>包外调用：没有包外调用；<code>substitute_params()</code> 和 <code>add_params()</code> 使用。</li></ul><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node.ros__parameters.plugins.0.name</span></span></code></pre></div><p>可以表示列表中的某个叶值。但原始 YAML 键若含点号，会与层级表达产生歧义。函数也只记录叶值路径，不会记录一个字典节点本身的路径。</p><h2 id="十、cmake-的公开宏" tabindex="-1">十、CMake 的公开宏 <a class="header-anchor" href="#十、cmake-的公开宏" aria-label="Permalink to &quot;十、CMake 的公开宏&quot;">​</a></h2><h3 id="_10-1-nav2-package" tabindex="-1">10.1 <code>nav2_package()</code> <a class="header-anchor" href="#_10-1-nav2-package" aria-label="Permalink to &quot;10.1 `nav2_package()`&quot;">​</a></h3><ul><li>作用：给下游 Nav2 CMake 项目建立统一构建基线。</li><li>输入：没有宏参数，读取并修改当前 CMake 目录状态与缓存变量。</li><li>输出：没有返回值；可能设置构建类型、C++ 标准、编译选项、链接标志和 Windows 定义。</li><li>数据流／回调：在下游 <code>find_package(nav2_common REQUIRED)</code> 载入宏后，由对应 <code>CMakeLists.txt</code> 配置阶段显式调用。</li><li>包外调用：当前仓库有 32 个调用点，覆盖 AMCL、BT、Behavior、Controller、Costmap、Planner、Smoother、Map Server、Route、Velocity Smoother 等包和 DWB 子包。</li></ul><p>宏内部规则包括：</p><ul><li>单配置生成器没有显式构建类型时，把 <code>CMAKE_BUILD_TYPE</code> 强制缓存为 <code>Release</code>，并给 GUI 设置四个候选值。</li><li>没有显式 <code>CMAKE_CXX_STANDARD</code> 时设置 C++17。源码旁注仍写“默认 C++14”，代码才是实际事实。</li><li>GCC 或 Clang 增加 <code>-Wall -Wextra -Wpedantic -Werror -Wdeprecated -fPIC</code>。</li><li><code>COVERAGE_ENABLED</code> 默认关闭；开启时给编译、可执行链接和共享库链接加入 <code>--coverage</code>。</li><li>MSVC 开启 <code>CMAKE_WINDOWS_EXPORT_ALL_SYMBOLS</code>，并定义 <code>_USE_MATH_DEFINES</code>。</li></ul><p>这些设置作用在宏调用所在的 CMake 目录及其后续目标。宏不是目标级封装，因此调用顺序与子目录边界会影响覆盖范围。</p><p><img src="'+s+`" alt="nav2_package 宏从 Ament 导出到 32 个下游包"></p><h2 id="十一、四个-launch-工具在仓库外怎样被调用" tabindex="-1">十一、四个 Launch 工具在仓库外怎样被调用 <a class="header-anchor" href="#十一、四个-launch-工具在仓库外怎样被调用" aria-label="Permalink to &quot;十一、四个 Launch 工具在仓库外怎样被调用&quot;">​</a></h2><h3 id="_11-1-rewrittenyaml-的-25-个实例" tabindex="-1">11.1 RewrittenYaml 的 25 个实例 <a class="header-anchor" href="#_11-1-rewrittenyaml-的-25-个实例" aria-label="Permalink to &quot;11.1 RewrittenYaml 的 25 个实例&quot;">​</a></h3><p>生产 Bringup 中，<code>nav2_bringup</code>、<code>myagv_test_bringup</code>、<code>mytb3_bringup</code>、<code>myworld_bringup</code>、<code>nav2_simple_commander</code>、<code>nav2_collision_monitor</code> 和 <code>nav2_regulated_modules</code> 都在使用它；<code>nav2_system_tests</code> 的行为、Costmap Filter、系统失败和 Waypoint 测试 Launch 也在使用。</p><p>最常见的数据流是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>params_file</span></span>
<span class="line"><span>  + namespace</span></span>
<span class="line"><span>  + use_sim_time</span></span>
<span class="line"><span>  + autostart／yaml_filename</span></span>
<span class="line"><span>  → RewrittenYaml</span></span>
<span class="line"><span>  → ParameterFile(allow_substs=True)</span></span>
<span class="line"><span>  → 多个 Nav2 节点</span></span></code></pre></div><p>因此一个 <code>use_sim_time</code> Launch 参数可以统一覆盖同一 YAML 中多个节点的同名字段。</p><h3 id="_11-2-replacestring-的四个实例" tabindex="-1">11.2 ReplaceString 的四个实例 <a class="header-anchor" href="#_11-2-replacestring-的四个实例" aria-label="Permalink to &quot;11.2 ReplaceString 的四个实例&quot;">​</a></h3><p>标准 <code>bringup_launch.py</code> 用它在多机器人参数模板中把 <code>&lt;robot_namespace&gt;</code> 替换成真实 namespace。标准 RViz Launch、<code>myagv_test_bringup</code> RViz Launch 和 <code>nav2_regulated_modules</code> RViz Launch 则用它改 RViz 配置中的同名占位符。</p><p>这里选择文本替换而不是 YAML 改写，是因为 RViz 配置和占位符场景只需要保持原文件其余内容不变。</p><h3 id="_11-3-hasnodeparams-的一个实例" tabindex="-1">11.3 HasNodeParams 的一个实例 <a class="header-anchor" href="#_11-3-hasnodeparams-的一个实例" aria-label="Permalink to &quot;11.3 HasNodeParams 的一个实例&quot;">​</a></h3><p><code>nav2_bringup/slam_launch.py</code> 同时创建两个 IncludeLaunchDescription：</p><ul><li>参数文件含 <code>slam_toolbox</code> 顶层键时，条件文本为真，传入 <code>slam_params_file</code>。</li><li>参数文件不含该键时，反向条件成立，不传用户参数文件，让 SLAM Toolbox 使用自己的默认文件。</li></ul><p>两条分支互斥，但判断对象相同。它解决的是“是否应该传参数文件”，不是检查单个 ROS 参数是否存在。</p><h3 id="_11-4-parsemultirobotpose-的一个实例" tabindex="-1">11.4 ParseMultiRobotPose 的一个实例 <a class="header-anchor" href="#_11-4-parsemultirobotpose-的一个实例" aria-label="Permalink to &quot;11.4 ParseMultiRobotPose 的一个实例&quot;">​</a></h3><p><code>cloned_multi_tb3_simulation_launch.py</code> 在生成 LaunchDescription 时立即解析 <code>robots:=...</code>，再用普通 Python 循环为每个机器人创建 RViz、仿真实体和 Nav2 Bringup。</p><p>这条链与另外三个工具不同：没有 <code>perform(context)</code>，也没有临时文件。输出直接成为 Launch Action 列表的结构输入。</p><h2 id="十二、源码中最容易误判的边界" tabindex="-1">十二、源码中最容易误判的边界 <a class="header-anchor" href="#十二、源码中最容易误判的边界" aria-label="Permalink to &quot;十二、源码中最容易误判的边界&quot;">​</a></h2><h3 id="_12-1-convert-types-false-仍会转布尔值" tabindex="-1">12.1 <code>convert_types=False</code> 仍会转布尔值 <a class="header-anchor" href="#_12-1-convert-types-false-仍会转布尔值" aria-label="Permalink to &quot;12.1 \`convert_types=False\` 仍会转布尔值&quot;">​</a></h3><p>数字转换受开关控制，<code>true</code> 和 <code>false</code> 转布尔不受控制。若调用者真的需要字符串 <code>&quot;true&quot;</code>，不能只依赖关闭 <code>convert_types</code>。</p><h3 id="_12-2-同名改写可能替换整棵子树" tabindex="-1">12.2 同名改写可能替换整棵子树 <a class="header-anchor" href="#_12-2-同名改写可能替换整棵子树" aria-label="Permalink to &quot;12.2 同名改写可能替换整棵子树&quot;">​</a></h3><p><code>getYamlLeafKeys()</code> 实际生成所有字典键引用。改写键若与一个父级映射键同名，<code>setValue()</code> 可以把整个子字典替换成标量。参数名应尽量选择真正的 ROS 参数叶键，结构改写则用更精确的机制。</p><h3 id="_12-3-临时文件失败可能延迟暴露" tabindex="-1">12.3 临时文件失败可能延迟暴露 <a class="header-anchor" href="#_12-3-临时文件失败可能延迟暴露" aria-label="Permalink to &quot;12.3 临时文件失败可能延迟暴露&quot;">​</a></h3><p><code>ReplaceString.perform()</code> 捕获错误后仍可能返回临时路径。真正的失败可能直到 RViz 或节点读取配置时才出现，看起来像下游解析故障。排障时应先核对 Launch 返回的临时文件内容。</p><h3 id="_12-4-parsemultirobotpose-对输入格式很信任" tabindex="-1">12.4 ParseMultiRobotPose 对输入格式很信任 <a class="header-anchor" href="#_12-4-parsemultirobotpose-对输入格式很信任" aria-label="Permalink to &quot;12.4 ParseMultiRobotPose 对输入格式很信任&quot;">​</a></h3><p>它只补默认字段，不验证数值是否有限、四元数是否合法或 namespace 是否可用。后续 Gazebo 与 Nav2 启动失败时，根因可能仍是最初的命令行 Pose 文本。</p><h3 id="_12-5-cmake-宏把警告提升为错误" tabindex="-1">12.5 CMake 宏把警告提升为错误 <a class="header-anchor" href="#_12-5-cmake-宏把警告提升为错误" aria-label="Permalink to &quot;12.5 CMake 宏把警告提升为错误&quot;">​</a></h3><p>GCC／Clang 分支包含 <code>-Werror</code>。下游依赖升级后新增的弃用告警可能直接让构建失败。这是统一质量门槛带来的有意结果，排障时不要简单归因为编译器“太严格”。</p><h2 id="十三、建议的源码阅读顺序" tabindex="-1">十三、建议的源码阅读顺序 <a class="header-anchor" href="#十三、建议的源码阅读顺序" aria-label="Permalink to &quot;十三、建议的源码阅读顺序&quot;">​</a></h2><h3 id="_13-1-从实际-launch-调用点进入" tabindex="-1">13.1 从实际 Launch 调用点进入 <a class="header-anchor" href="#_13-1-从实际-launch-调用点进入" aria-label="Permalink to &quot;13.1 从实际 Launch 调用点进入&quot;">​</a></h3><p>先看 <code>nav2_bringup/launch/bringup_launch.py</code> 中 <code>ReplaceString</code> 与 <code>RewrittenYaml</code> 如何串联，再回到两个类的 <code>perform()</code>。这样能先知道输入和消费者，不会把工具函数当成孤立算法。</p><h3 id="_13-2-顺着-rewrittenyaml-的固定流水线下钻" tabindex="-1">13.2 顺着 RewrittenYaml 的固定流水线下钻 <a class="header-anchor" href="#_13-2-顺着-rewrittenyaml-的固定流水线下钻" aria-label="Permalink to &quot;13.2 顺着 RewrittenYaml 的固定流水线下钻&quot;">​</a></h3><p>从 <code>perform()</code> 依次进入 <code>resolve_rewrites()</code>、<code>substitute_params()</code>、<code>add_params()</code>、<code>substitute_keys()</code> 和 <code>substitute_values()</code>，再分别追踪 <code>pathify()</code>、<code>getYamlLeafKeys()</code>、<code>updateYamlPathVals()</code> 与 <code>convert()</code>。</p><h3 id="_13-3-把另外三个-launch-工具看成不同粒度" tabindex="-1">13.3 把另外三个 Launch 工具看成不同粒度 <a class="header-anchor" href="#_13-3-把另外三个-launch-工具看成不同粒度" aria-label="Permalink to &quot;13.3 把另外三个 Launch 工具看成不同粒度&quot;">​</a></h3><ul><li><code>ReplaceString</code> 面向文件文本。</li><li><code>HasNodeParams</code> 面向 YAML 顶层结构和条件分支。</li><li><code>ParseMultiRobotPose</code> 面向 ROS 2 Launch 进程命令行。</li></ul><p>三者输入层级不同，不能互相替代。</p><h3 id="_13-4-最后阅读-cmake-导出链" tabindex="-1">13.4 最后阅读 CMake 导出链 <a class="header-anchor" href="#_13-4-最后阅读-cmake-导出链" aria-label="Permalink to &quot;13.4 最后阅读 CMake 导出链&quot;">​</a></h3><p>从本包 <code>CMakeLists.txt</code> 的 <code>CONFIG_EXTRAS</code> 进入 <code>nav2_common-extras.cmake</code>，再进入 <code>nav2_package.cmake</code>，最后任选一个下游包核对 <code>find_package()</code> 与 <code>nav2_package()</code> 的调用顺序。</p><h2 id="十四、把-32-个入口压缩成一张心智图" tabindex="-1">十四、把 32 个入口压缩成一张心智图 <a class="header-anchor" href="#十四、把-32-个入口压缩成一张心智图" aria-label="Permalink to &quot;十四、把 32 个入口压缩成一张心智图&quot;">​</a></h2><h3 id="_14-1-launch-平面的核心" tabindex="-1">14.1 Launch 平面的核心 <a class="header-anchor" href="#_14-1-launch-平面的核心" aria-label="Permalink to &quot;14.1 Launch 平面的核心&quot;">​</a></h3><p><code>RewrittenYaml</code> 处理结构化配置，<code>ReplaceString</code> 处理模板文本，<code>HasNodeParams</code> 决定参数分支，<code>ParseMultiRobotPose</code> 把命令行压成 Launch 结构。前三者依赖 Launch 延迟求值，后者在普通 Python 执行阶段立即完成。</p><h3 id="_14-2-cmake-平面的核心" tabindex="-1">14.2 CMake 平面的核心 <a class="header-anchor" href="#_14-2-cmake-平面的核心" aria-label="Permalink to &quot;14.2 CMake 平面的核心&quot;">​</a></h3><p><code>nav2_package()</code> 不生成库，也不链接运行代码。它把 Release、C++17、严格告警、覆盖率和 Windows 导出规则统一注入调用它的下游目录。</p><h3 id="_14-3-真正的数据边界" tabindex="-1">14.3 真正的数据边界 <a class="header-anchor" href="#_14-3-真正的数据边界" aria-label="Permalink to &quot;14.3 真正的数据边界&quot;">​</a></h3><p>这个包接收的是“配置描述”，输出的是“启动前可消费的配置”或“编译前可继承的规则”。机器人位姿、地图、速度参数最终会进入具体节点，但 <code>nav2_common</code> 自己不持有导航状态，也不参与规划控制循环。</p><p>看懂它之后，再遇到“YAML 明明写的是一个值，节点为何读到另一个值”“namespace 为什么只在某些配置里生效”“同一批包为何突然把警告当错误”，就应该先检查启动前和构建前的这层基础设施，而不是直接怀疑运行中的 Nav2 算法。</p>`,187)])])}const f=a(u,[["render",p]]);export{k as __pageData,f as default};
